cases.sql:
SELECT id, quantity
FROM order_items
WHERE quantity BETWEEN (SELECT MIN(quantity) FROM order_items) AND (SELECT AVG(quantity) FROM order_items);

select t1.id, t1.duration_sec
from web_events t1
where t1.duration_sec >= (select avg(t2.duration_sec) from web_events t2 where t2.event_type = 'search');

select a.id, a.units, a.sale_date, a.revenue
from store_sales as a
where a.units < (select max(b.units) from store_sales as b where b.product_id = 3);

SELECT t1.id, t1.status, t1.discount, t1.shipping_fee, t1.channel
FROM orders AS t1
WHERE t1.discount < (SELECT MAX(t2.discount) FROM orders AS t2);

SELECT o.id, o.status, o.monthly_fee, o.end_date
FROM subscriptions o
WHERE o.monthly_fee >= (SELECT AVG(i.monthly_fee) FROM subscriptions i WHERE i.status = 'ACTIVE');

SELECT o.id, o.status, o.amount
FROM payments o
WHERE o.amount > (SELECT MIN(i.amount) FROM payments i WHERE i.status = o.status AND i.amount <= 1487);

SELECT a.id, a.plan, a.end_date, (SELECT MIN(b.end_date) FROM subscriptions AS b WHERE b.plan = a.plan) AS min_end_date
FROM subscriptions AS a
WHERE a.status = 'PAUSED';

SELECT p.id, p.opened_date, p.city, (SELECT AVG(c.revenue) FROM store_sales c WHERE p.id = c.store_id) AS store_sales_avg
FROM stores p
ORDER BY opened_date DESC;

select d.id, d.budget, (select min(e.hire_date) from employees as e where e.dept_id = d.id) as min_hire_date
from departments as d
order by min_hire_date;

select p.id, p.launch_date, p.cost
from products p
where 1 <= (select count(s.id) from store_sales s where s.product_id = p.id);

SELECT c.id, c.age, c.credit_limit
FROM customers AS c
WHERE (SELECT MAX(a.balance) FROM accounts AS a WHERE a.account_type IN ('LOAN', 'SAVINGS') AND a.customer_id = c.id) < 43759;

SELECT s.id, s.store_name, s.opened_date, s.sqft
FROM stores s
WHERE s.sqft <= (SELECT SUM(s2.revenue) FROM store_sales s2 WHERE s2.store_id = s.id);

select t1.id, t1.category, t1.price, (select max(t2.price) from products t2 where t2.category = t1.category) as category_max_price, t1.price - (select min(x.price) from products x) as diff_from_overall_min
from products t1
order by diff_from_overall_min;

SELECT a.id, a.city, a.sqft, a.sqft - (SELECT MAX(b.sqft) FROM stores b WHERE b.city = a.city) AS diff_from_city_max, a.sqft - (SELECT MAX(sqft) FROM stores WHERE opened_date > '2024-11-05') AS sqft_vs_all
FROM stores a
ORDER BY sqft_vs_all;

SELECT a.id, a.session_id, a.duration_sec, a.duration_sec - (SELECT AVG(b.duration_sec) FROM web_events b WHERE b.session_id = a.session_id) AS duration_sec_vs_session, ROUND(a.duration_sec * 100.0 / (SELECT SUM(duration_sec) FROM web_events WHERE session_id = 12), 2) AS pct_of_total
FROM web_events a
WHERE a.event_type = 'search';
